def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    # --- Endgame exploitation: last 4 rounds defect ---
    if n >= 96:
        return 'D'

    # --- Count opponent statistics ---
    opp_c = 0
    opp_d = 0
    for i in range(n):
        if opp(i) == 'D':
            opp_d += 1
        else:
            opp_c += 1

    # --- Recent window (last 12) ---
    w = 12 if n >= 12 else n
    start = n - w
    rec_opp_d = 0
    rec_opp_c = 0
    for i in range(start, n):
        if opp(i) == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1

    last_opp = opp(n - 1)
    last_me = me(n - 1)

    # --- Consecutive opponent defection streak ---
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp(i) == 'D':
            opp_d_streak += 1
        else:
            break

    # --- Consecutive opponent cooperation streak ---
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if opp(i) == 'C':
            opp_c_streak += 1
        else:
            break

    # Early game: cooperate, but probe early defectors
    if n < 5:
        if opp_d >= 1 and last_opp == 'D':
            return 'D'
        return 'C'

    # Persistent defector: don't waste time, defect
    if opp_d_streak >= 4:
        # Rarely probe to see if they've turned over a new leaf
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Direct retaliation for single defection but forgive if recent pattern good
    if last_opp == 'D':
        if rec_opp_d >= 4:
            return 'D'
        if opp_d_streak >= 2:
            return 'D'
        # last_opp just defected once: retaliate, but check if earlier we defected first
        if last_me == 'D':
            # they may be retaliating; de-escalate
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated.
    # Reward long cooperation streaks.
    if opp_c_streak >= 3:
        # Maintain cooperation; occasionally exploit only if opponent is extremely passive
        if opp_c >= 25 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Opponent cooperated but not long streak.
    # Watch for exploitation pattern: opponent defects after our cooperation
    if n >= 6:
        exploit_count = 0
        exploit_window = 0
        scan = 10 if n >= 10 else n
        for i in range(n - scan, n):
            if i > 0 and me(i - 1) == 'C' and opp(i) == 'D':
                exploit_count += 1
            exploit_window += 1
        if exploit_window > 0 and exploit_count * 2 >= exploit_window:
            return 'D'

    # If opponent overall is heavily cooperative, cooperate.
    if opp_c * 2 >= n * 1:
        # if we've been defecting a lot and they keep cooperating, exploit more
        my_d = 0
        for i in range(n):
            if me(i) == 'D':
                my_d += 1
        if my_d <= 1 and opp_c_streak >= 1 and n > 15:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    # Opponent mixed. Use retaliation tendency.
    if rec_opp_d >= 3:
        return 'D'
    if rng.random() < 0.15:
        return 'D'
    return 'C'
